# Rasterizes the Food4Rhino logo set in Lugworm/Resources/icons-src/food4rhino/
# (generated by tools/gen_food4rhino_logo.py) to PNGs next to the SVGs, with a
# transparent background.
#
# Food4Rhino needs images of at least 200x200 px and scales anything above
# 1920x1080 down: square instances render at 1024 px, wide ones at 1920 px
# wide, and workbench.svg at 1:1 as an overview. The PNGs stay in icons-src:
# Resources\*.png is embedded into the assembly. Rendering uses headless Edge
# like make_package_icon.ps1, with the same drop shadow scaled to the size.
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$dir = Join-Path $root 'Lugworm\Resources\icons-src\food4rhino'
$edge = 'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe'
if (-not (Test-Path $edge)) { throw "Edge not found at $edge" }
Add-Type -AssemblyName System.Drawing

function Render([string]$svgPath, [string]$outPath, [int]$w, [int]$h, [double]$scale, [bool]$shadow) {
    $tmp = Join-Path ([IO.Path]::GetTempPath()) ("f4rlogo-" + [guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Path $tmp | Out-Null
    try {
        $svg = [IO.File]::ReadAllText($svgPath)
        $svg = $svg.Substring($svg.IndexOf('<svg'))
        $sh = [math]::Round(2 * $scale, 2)
        $filter = if ($shadow) { "filter:drop-shadow(${sh}px ${sh}px ${sh}px rgba(0,0,0,.28))" } else { '' }
        $html = @"
<!doctype html><html><head><meta charset='utf-8'><style>
html,body{margin:0;padding:0;width:${w}px;height:${h}px;overflow:hidden;background:transparent}
svg{display:block;width:${w}px;height:${h}px;$filter}
</style></head><body>$svg</body></html>
"@
        $htmlPath = Join-Path $tmp 'logo.html'
        [IO.File]::WriteAllText($htmlPath, $html, [Text.UTF8Encoding]::new($false))
        # Start-Process for the same reason as make_package_icon.ps1: Edge's benign
        # stderr noise would otherwise become a terminating NativeCommandError
        $edgeArgs = @('--headless=new', '--disable-gpu', '--disable-crash-reporter', '--no-first-run',
                      '--hide-scrollbars', '--force-device-scale-factor=1', '--default-background-color=00000000',
                      '--virtual-time-budget=3000', "--user-data-dir=$tmp\profile",
                      "--screenshot=$outPath", "--window-size=$w,$h", ('file:///' + $htmlPath.Replace('\', '/')))
        $p = Start-Process -FilePath $edge -ArgumentList $edgeArgs -Wait -PassThru -WindowStyle Hidden `
            -RedirectStandardError (Join-Path $tmp 'edge-stderr.log')
        if ($p.ExitCode -ne 0) { throw "Edge exited with $($p.ExitCode) on $svgPath" }
        $img = [System.Drawing.Image]::FromFile($outPath)
        try { if ($img.Width -ne $w -or $img.Height -ne $h) { throw "$outPath is $($img.Width)x$($img.Height), expected ${w}x${h}" } }
        finally { $img.Dispose() }
        Write-Host "wrote $outPath (${w}x${h})"
    }
    finally { Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue }
}

foreach ($f in Get-ChildItem $dir -Filter *.svg) {
    $head = [IO.File]::ReadAllText($f.FullName)
    if ($head -notmatch 'viewBox="0 0 ([\d.]+) ([\d.]+)"') { throw "no viewBox in $($f.Name)" }
    $vw = [double]$Matches[1]; $vh = [double]$Matches[2]
    if ($f.BaseName -eq 'workbench') { $scale = 1.0; $shadow = $false }
    elseif ($vw -eq $vh) { $scale = 1024 / $vw; $shadow = $true }
    else { $scale = 1920 / $vw; $shadow = $true }
    $w = [int][math]::Round($vw * $scale); $h = [int][math]::Round($vh * $scale)
    Render $f.FullName ([IO.Path]::ChangeExtension($f.FullName, '.png')) $w $h $scale $shadow
}
